<template>
  <Card>
    <CardHeader class="grid grid-cols-12">
      <div class="flex flex-col gap-1 w-full col-span-12 md:col-span-9">
        <CardTitle class="text-[20px]/[28px] text-wrap">{{ item.name }}</CardTitle>
        <CardDescription class="text-[16px]/[28px]">
          <p class="w-full line-clamp-1">{{ item.short_description }}</p>
        </CardDescription>
      </div>
      <div class="flex md:justify-end col-span-3">
        <Badge v-if="isCanvasserItem(item) && item.status" :variant="getApplicationStatus(item.status).variant">{{
          getApplicationStatus(item.status).label
        }}</Badge>
        <NewApplicationsBadge
          v-if="isManagerOrAdminItem(item) && item.new_requests > 0"
          :new-applications="item.new_requests"
        />
      </div>
    </CardHeader>
    <CardContent class="pb-0 flex flex-wrap gap-4">
      <IconLabelValue :icon="BriefcaseBusiness" label="Type">
        <span class="capitalize">{{ item.type }}</span>
      </IconLabelValue>
      <IconLabelValue :icon="CalendarDays" label="Duration" :value="startEndDate(item.start_date, item.end_date)" />
      <IconLabelValue
        v-if="isSignatureProjectGoal(item.goal) && isManagerOrAdminItem(item)"
        :icon="CircleCheck"
        label="Goal"
        :value="goal(item.goal)"
      />
      <IconLabelValue
        v-if="isManagerOrAdminItem(item)"
        :icon="Users"
        label="Approved Canvassers"
        :value="approvedCanvassers(item)"
      />
    </CardContent>
    <CardFooter>
      <div class="px-2 py-4">
        <NuxtLink
          :to="{ name: 'applications-id', params: { id: item.id } }"
          class="text-accent2-foreground text-[14px]/[24px]"
        >
          View Details ->
        </NuxtLink>
      </div>
    </CardFooter>
  </Card>
</template>

<script setup lang="ts">
import { cn } from '~/components/ui/utils';
import { CircleCheck, CalendarDays, Users, BriefcaseBusiness } from 'lucide-vue-next';
import type {
  UpcomingProjectListItemForManager,
  UpcomingProjectListItemForAdmin,
  UpcomingProjectListItemForCanvasser,
} from '~/client';
import { getApplicationStatus } from '~/constants/applications';

interface Props {
  item: UpcomingProjectListItemForManager | UpcomingProjectListItemForAdmin | UpcomingProjectListItemForCanvasser;
}

defineProps<Props>();

function approvedCanvassers(item: UpcomingProjectListItemForAdmin | UpcomingProjectListItemForManager) {
  return `${item.approved_canvassers}/${item.staffing_goal}`;
}

function isCanvasserItem(
  item: UpcomingProjectListItemForManager | UpcomingProjectListItemForAdmin | UpcomingProjectListItemForCanvasser
): item is UpcomingProjectListItemForCanvasser {
  return 'status' in item;
}

function isManagerOrAdminItem(
  item: UpcomingProjectListItemForManager | UpcomingProjectListItemForAdmin | UpcomingProjectListItemForCanvasser
): item is UpcomingProjectListItemForManager | UpcomingProjectListItemForAdmin {
  return 'new_requests' in item;
}
</script>

<style scoped lang="scss"></style>
